						teams->getTeamFromPlayer(player),
						stat->getName(),
						Value<int, &sIntValue> /* PORT: 2008 pointer-to-name template argument. */::desc_Value.getValue(stat)
					);
				}
			}
		}
	}

	if (teams != NULL) {
