			Team* team = dynamic_cast<Team*>(teams->getChild(i));

			for (unsigned int j = 0; j < statNamesList.size(); ++j) {
				teamTotals[team][statNamesList[j]] = 0;

				for (unsigned int k = 0; k < playersByTeamList[team].size(); ++k) {
